arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Content-Type: application/x-www-form-urlencoded" --data "token=<TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR',d.get('error')); sys.exit()
for m in d['members']:
    real = (m.get('profile') or {}).get('real_name','')
    if 'maya' in (real or '').lower() or 'maya' in (m.get('profile') or {}).get('display_name','').lower():
        print(m['id'], '|', real, '|', m.get('profile',{}).get('display_name',''), '|', m.get('deleted'))
"

